using System.Collections;
using LittleLeo;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "MoveOrbsAction", menuName = "Data/Battle/Battle Actions/Orion/MoveOrbs Action")]
public class MoveOrbsAction : BattleAction
{
	public enum MoveOrbsEnum
	{
		CLOCKWISE,
		COUNTERCLOCKWISE,
		BACKANDFORTH
	}

	[Header("Action Specifics")]
	[SerializeField]
	private MoveOrbsEnum moveOrbsEnum;

	public override void CastAmount(int amount, GameObject source)
	{
		if (moveOrbsEnum == MoveOrbsEnum.BACKANDFORTH)
		{
			ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(CastCoroutine(ReferenceSingleton<BattleHandler>.Instance.GetOrionAstrarium(source).MoveOrbsBackAndForthCoroutine(amount), source));
			ReferenceSingleton<GameStateManager>.Instance.SetState(ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState);
		}
		else
		{
			int movementAmount = ((moveOrbsEnum == MoveOrbsEnum.COUNTERCLOCKWISE) ? (-amount) : amount);
			ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(CastCoroutine(ReferenceSingleton<BattleHandler>.Instance.GetOrionAstrarium(source).MoveOrbsCoroutine(movementAmount), source));
			ReferenceSingleton<GameStateManager>.Instance.SetState(ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState);
		}
	}

	private IEnumerator CastCoroutine(IEnumerator coroutineToUse, GameObject source)
	{
		CheckCancelAutoOnDiceCastedOnRuneCasted(source);
		yield return ReferenceSingleton<CoroutineHandler>.Instance.Run(coroutineToUse);
	}
}
